/**
 * Answered within an SLA. An appeals process with no deadline is a way of
saying no slowly, and the app stores treat "users cannot appeal" as a
policy violation rather than a product choice.

An appeal is never reviewed by the person whose decision is being appealed
- enforced by a database constraint, not by rota discipline.

 * @summary Challenge a moderation decision
 */
export const openAppeal = (
    openAppealBody: OpenAppealBody,
 signal?: AbortSignal
) => {
      
      
      return apiFetch<OpenAppeal201>(
      {url: `/appeals`, method: 'POST',
      headers: {'Content-Type': 'application/json', },
      data: openAppealBody, signal
    },
      );
    }
  


export const getOpenAppealMutationOptions = <TError = UnprocessableEntityResponse,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof openAppeal>>, TError,{data: OpenAppealBody}, TContext>, }
): UseMutationOptions<Awaited<ReturnType<typeof openAppeal>>, TError,{data: OpenAppealBody}, TContext> => {

const mutationKey = ['openAppeal'];
const {mutation: mutationOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }};

      


      const mutationFn: MutationFunction<Awaited<ReturnType<typeof openAppeal>>, {data: OpenAppealBody}> = (props) => {
          const {data} = props ?? {};

          return  openAppeal(data,)
        }

        


  return  { mutationFn, ...mutationOptions }}

    export type OpenAppealMutationResult = NonNullable<Awaited<ReturnType<typeof openAppeal>>>
    export type OpenAppealMutationBody = OpenAppealBody
    export type OpenAppealMutationError = UnprocessableEntityResponse

